package main

import (
	"bytes"
	"encoding/json"
	"os"
	"path/filepath"
	"reflect"
	"testing"

	"github.com/cplieger/deadset-spec/v8/vocab"
)

// generatedModule is a target holding two generated files, one whose header opens
// the file and one whose header follows a licence comment, beside a hand-written one.
func generatedModule(t *testing.T) string {
	t.Helper()
	return writeModule(t, map[string]string{
		"go.mod":  "module example.com/app\n\ngo 1.27.1\n",
		"main.go": "package main\n\nfunc main() { mocked(); colour() }\n",
		"mock.go": "// Code generated by MockGen. DO NOT EDIT.\n\npackage main\n\nfunc mocked() {}\n",
		"colour_string.go": "// Copyright the authors.\n\n// Code generated by \"stringer -type=Colour\"; DO NOT EDIT.\n\n" +
			"package main\n\nfunc colour() {}\n",
		repositoryDocument: `{"target": {"kind": "application"}}`,
	})
}

// analyzeWithFacts runs analyze over dir with --facts, and returns the facts
// document decoded as plain JSON values and the report's bytes.
func analyzeWithFacts(t *testing.T, dir string) (map[string]any, []byte) {
	t.Helper()
	factsPath := filepath.Join(t.TempDir(), "facts.json")
	got := runAnalyze(t, dir, "--facts="+factsPath)
	if got.code == vocab.ExitUsage || got.code == vocab.ExitFailure {
		t.Fatalf("analyze --facts = %d, want a verdict\nstderr:\n%s", got.code, got.stderr)
	}
	body, err := os.ReadFile(factsPath)
	if err != nil {
		t.Fatalf("analyze --facts wrote no facts document: %v", err)
	}
	var facts map[string]any
	if err := json.Unmarshal(body, &facts); err != nil {
		t.Fatalf("decode the facts document: %v\n%s", err, body)
	}
	reportBody, err := os.ReadFile(got.reportPath)
	if err != nil {
		t.Fatalf("read the report: %v", err)
	}
	return facts, reportBody
}

func TestAnalyzeWritesAFactsDocumentAndTheSameReport(t *testing.T) {
	dir := generatedModule(t)
	facts, withFacts := analyzeWithFacts(t, dir)
	without := runAnalyze(t, dir)
	plain, err := os.ReadFile(without.reportPath)
	if err != nil {
		t.Fatalf("read the report: %v", err)
	}
	if !bytes.Equal(plain, withFacts) {
		t.Errorf("the report with --facts differs from the one without it:\nwith:\n%s\nwithout:\n%s", withFacts, plain)
	}
	if facts["language"] != "go" || facts["evaluated"] != false {
		t.Errorf("the facts document names language %v and evaluated %v, want go and false", facts["language"], facts["evaluated"])
	}
	analyzer, _ := facts["analyzer"].(map[string]any)
	if analyzer["name"] != name || analyzer["version"] != version() {
		t.Errorf("the facts document names the analyzer %v, want %s %s", analyzer, name, version())
	}
	if v, _ := facts["facts_version"].(string); v == "" {
		t.Errorf("the facts document names no facts_version: %v", facts)
	}
	if b, ok := facts["bindings"].([]any); !ok || len(b) != 0 {
		t.Errorf("the facts document of a target with no schema output holds the bindings %v, want none", facts["bindings"])
	}
}

func TestFactsNameEveryGeneratedFileByItsHeaderLine(t *testing.T) {
	facts, _ := analyzeWithFacts(t, generatedModule(t))
	want := []any{
		map[string]any{
			"path": "colour_string.go", "line": float64(3), "evidence": "header",
			"detail": `// Code generated by "stringer -type=Colour"; DO NOT EDIT.`,
		},
		map[string]any{
			"path": "mock.go", "line": float64(1), "evidence": "header",
			"detail": "// Code generated by MockGen. DO NOT EDIT.",
		},
	}
	if got := facts["generated"]; !reflect.DeepEqual(got, want) {
		t.Errorf("the facts document's generated files are\n%v\nwant\n%v", got, want)
	}
}
